import sys, re, difflib

def load(path, func_pat):
    fn = None; seq = {}
    for line in open(path):
        m = re.match(r'^[0-9a-f]+ <(.+)>:', line)
        if m:
            fn = m.group(1); seq[fn] = []
            continue
        if fn is None: continue
        if '\t' not in line: continue
        parts = line.rstrip('\n').split('\t')
        if len(parts) >= 3 and ':' in parts[0]:
            instr = parts[2].strip()   # mnemonic
            if len(parts) >= 4: instr += '\t' + parts[3].strip()  # operands
            seq[fn].append(instr)
    return {k: v for k, v in seq.items() if re.search(func_pat, k)}

def mnem(instr):
    return instr.split('\t')[0].split()[0]

before, after, pat = sys.argv[1], sys.argv[2], sys.argv[3]
bd = load(before, pat); ad = load(after, pat)
for k in bd:
    if k not in ad:
        print(f"FUNC MISSING AFTER: {k}"); continue
    bm = [mnem(x) for x in bd[k]]; am = [mnem(x) for x in ad[k]]
    sm = difflib.SequenceMatcher(None, bm, am, autojunk=False)
    ops = [o for o in sm.get_opcodes() if o[0] != 'equal']
